for (blk=0;blk<n;blk+=W){ // W-lane warp block
  for (i=0;i<W;i++){
    for (t=0;t<maxNNZperRow;t++){
      val = ellVal[i][t]; col = ellCol[i][t];
      out[blk+i] += (col>=0 ? val*B[col] : 0);
    }
  }
}

for (i=0;i<n;i++){
  table.clear();
  for (k=rowPtrA[i];k<rowPtrA[i+1];k++){
    aVal=AValA[k]; j=colIdxA[k];
    for (t=rowPtrB[j];t<rowPtrB[j+1];t++){
      colB=colIdxB[t]; table.add(colB, aVal*BVal[t]);
    }
  }
  out[i]=table.materialize();
}

for (ii=0;ii<n;ii+=Ti) for (jj=0;jj<n;jj+=Tj){
  // Gustavson-style partial accumulation
  for (i=ii;i<min(ii+Ti,n);i++){
    marker.clear();
    for (k=rowPtrA[i];k<rowPtrA[i+1];k++){
      kk=colIdxA[k]; a=AValA[k];
      for (t=rowPtrB[kk];t<rowPtrB[kk+1];t++){
        j=colIdxB[t]; if (j>=jj && j<jj+Tj){ outTile[i-jj][j-jj]+=a*BVal[t]; }
      }
    }
  }
}
